js:
var SITE = 'https://sexaix.top';
var API = SITE + '/api';
var UA = 'Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36';
var MD = 'https://img.mfantasy.net';
function jGet(url) {
  try { return fetch(url, {headers: {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'application/json, text/plain, */*'}}); } catch (e) { return ''; }
}
function jFix(u) {
  if (!u) return '';
  u = String(u).trim();
  if (!u || u.charAt(0) === '#') return u;
  if (/^(?:[a-z][a-z\d+\-.]*:)?\/\//i.test(u) || u.indexOf('data:') === 0 || u.indexOf('blob:') === 0) return u;
  if (u.indexOf('/images/') === 0 || u.indexOf('/assets/') === 0) return u;
  if (u.indexOf('/api/') === 0) return SITE + u;
  return MD + '/' + u.replace(/^\/+/, '');
}
function jCard(d) {
  if (!d || d.id === undefined || !d.title) return null;
  var bits = [];
  if (d.categoryName) bits.push(d.categoryName);
  if (d.totalEpisodes) bits.push('共' + d.totalEpisodes + '集');
  if (d.viewCount) bits.push('播放' + d.viewCount);
  return {title: d.title, img: jFix(d.coverUrl || ''), desc: bits.join(' · '), url: 'sexaix:' + d.id, extra: {intro: d.intro || d.shareDesc || ''}};
}
function jCards(rows) {
  var out = [], seen = {};
  for (var i = 0; i < (rows || []).length; i++) { var c = jCard(rows[i]); if (c && !seen[c.url]) { seen[c.url] = 1; out.push(c); } }
  return out;
}
function jList() {
  var d = null;
  try { d = JSON.parse(jGet(API + '/dramas?language=zh-CN')); } catch (e) {}
  if (d && d.code === 0 && Array.isArray(d.data)) return d.data;
  return [];
}
function jPage(rows, pg) {
  var start = (pg - 1) * 20;
  return jCards((rows || []).slice(start, start + 20));
}

var items = [];
try {
  var cls = 'all'; var pg = 1;
  try { if (typeof MY_URL !== 'undefined' && MY_URL) { var pp = String(MY_URL).split('##'); if (pp.length > 1 && pp[1]) cls = pp[1]; } } catch (e) {}
  try { if (typeof MY_PAGE !== 'undefined' && MY_PAGE) pg = parseInt(MY_PAGE) || 1; } catch (e) {}
  if (cls === 'all') {
    items = jPage(jList(), pg);
  } else {
    var d2 = null;
    try { d2 = JSON.parse(jGet(API + '/dramas?language=zh-CN&categoryId=' + encodeURIComponent(cls))); } catch (e) {}
    var rows = (d2 && d2.code === 0 && Array.isArray(d2.data)) ? d2.data : [];
    items = jPage(rows, pg);
  }
} catch (e) { items = []; }
setResult(items);

