      items.push({title: '剧情简介', col_type: 'text_center_1', extra: {lineVisible: false}, url: 'hiker://empty'});
      items.push({title: '&nbsp;&nbsp;&nbsp;&nbsp;' + String(intro).replace(/\n/g, '<br/>&nbsp;&nbsp;&nbsp;&nbsp;'), col_type: 'rich_text'});
    }
    items.push({title: '播放线路：在线播放', col_type: 'text_1', url: 'hiker://empty'});
