      if (!ep.isUnlocked) { locked++; label = label + '·需解锁'; items.push({title: label, url: 'hiker://empty', desc: '需解锁（' + (ep.unlockPoints || 0) + '积分）', img: poster}); }
      else { items.push({title: label, url: jFix(ep.videoUrl || ''), desc: '可播', img: poster}); }
