    if (locked) items.push({title: locked + '集需解锁（登录+积分，站内解锁）', col_type: 'text_1', url: 'hiker://empty'});
    var car = jFix(s.carouselImageUrl || '');
    if (car && car !== poster) items.push({title: '本片剧照', col_type: 'text_center_1', extra: {lineVisible: false}, url: 'hiker://empty'});
    if (car && car !== poster) items.push({title: '', img: car, pic_url: car, url: 'hiker://empty'});
  }
} catch (e) { items = []; }
setResult(items);

